BEGIN;
ALTER TABLE users DROP CONSTRAINT IF EXISTS users_role_check;
ALTER TABLE users ADD CONSTRAINT users_role_check CHECK(role IN('admin','teacher','student','parent'));
ALTER TABLE tests ADD COLUMN IF NOT EXISTS story_id BIGINT;
ALTER TABLE tests ADD COLUMN IF NOT EXISTS time_limit_min INTEGER;
ALTER TABLE tests ADD COLUMN IF NOT EXISTS due_at BIGINT;
ALTER TABLE tests ADD COLUMN IF NOT EXISTS updated_at BIGINT;
ALTER TABLE tests ADD COLUMN IF NOT EXISTS archived INTEGER NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS stories(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT NOT NULL,level TEXT NOT NULL,story TEXT NOT NULL,summary TEXT,setting TEXT,time_period TEXT,characters TEXT,events TEXT,lesson TEXT,author TEXT,language TEXT DEFAULT 'English',licence TEXT,source_name TEXT,source_url TEXT,tags TEXT,cover_path TEXT,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','archived')),created_by BIGINT REFERENCES users(id),created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS classes(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,level TEXT NOT NULL,academic_year TEXT NOT NULL,created_at BIGINT NOT NULL,UNIQUE(name,academic_year));
CREATE TABLE IF NOT EXISTS class_members(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,class_id BIGINT NOT NULL REFERENCES classes(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,member_role TEXT NOT NULL CHECK(member_role IN('teacher','student')),created_at BIGINT NOT NULL,UNIQUE(class_id,user_id));
CREATE TABLE IF NOT EXISTS test_classes(test_id BIGINT NOT NULL REFERENCES tests(id) ON DELETE CASCADE,class_id BIGINT NOT NULL REFERENCES classes(id) ON DELETE CASCADE,PRIMARY KEY(test_id,class_id));
CREATE TABLE IF NOT EXISTS question_bank(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,story_id BIGINT REFERENCES stories(id) ON DELETE CASCADE,bloom TEXT NOT NULL,section TEXT,type TEXT NOT NULL,question TEXT NOT NULL,answer TEXT,options TEXT,marks INTEGER NOT NULL DEFAULT 1,source TEXT NOT NULL DEFAULT 'teacher',approved INTEGER NOT NULL DEFAULT 0,created_by BIGINT REFERENCES users(id),created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS resources(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,story_id BIGINT REFERENCES stories(id) ON DELETE CASCADE,owner_id BIGINT REFERENCES users(id),name TEXT NOT NULL,mime_type TEXT NOT NULL,size_bytes BIGINT NOT NULL,storage_path TEXT NOT NULL UNIQUE,resource_type TEXT NOT NULL DEFAULT 'attachment',created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS import_jobs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT REFERENCES users(id),filename TEXT,kind TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'review',details TEXT,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS parent_links(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,parent_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,student_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at BIGINT NOT NULL,UNIQUE(parent_id,student_id));
CREATE TABLE IF NOT EXISTS story_reads(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,story_id BIGINT NOT NULL REFERENCES stories(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,read_at BIGINT NOT NULL,UNIQUE(story_id,user_id));
CREATE TABLE IF NOT EXISTS rewards(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,points INTEGER NOT NULL DEFAULT 0,streak INTEGER NOT NULL DEFAULT 0,badges TEXT NOT NULL DEFAULT '[]',updated_at BIGINT NOT NULL,UNIQUE(user_id));
CREATE TABLE IF NOT EXISTS announcements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT NOT NULL,body TEXT NOT NULL,target_role TEXT,target_class_id BIGINT REFERENCES classes(id) ON DELETE CASCADE,expires_at BIGINT,created_by BIGINT REFERENCES users(id),created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_usage(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,day TEXT NOT NULL,calls INTEGER NOT NULL DEFAULT 0,input_tokens BIGINT NOT NULL DEFAULT 0,output_tokens BIGINT NOT NULL DEFAULT 0,UNIQUE(user_id,day));
CREATE TABLE IF NOT EXISTS reading_days(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,read_day TEXT NOT NULL,created_at BIGINT NOT NULL,UNIQUE(user_id,read_day));
CREATE TABLE IF NOT EXISTS teacher_comments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,attempt_id BIGINT NOT NULL UNIQUE REFERENCES attempts(id) ON DELETE CASCADE,teacher_id BIGINT NOT NULL REFERENCES users(id),comment TEXT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS attempt_history(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,old_attempt_id BIGINT NOT NULL,test_id BIGINT NOT NULL REFERENCES tests(id),user_id BIGINT NOT NULL REFERENCES users(id),answers TEXT,got INTEGER,by_level TEXT,status TEXT NOT NULL,started_at BIGINT,finished_at BIGINT,teacher_comment TEXT,archived_at BIGINT NOT NULL,archived_by BIGINT REFERENCES users(id),reason TEXT NOT NULL DEFAULT 'retake');
CREATE TABLE IF NOT EXISTS login_rate_limits(bucket TEXT PRIMARY KEY,attempts INTEGER NOT NULL,window_start BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS schema_migrations(name TEXT PRIMARY KEY,applied_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_stories_level_status ON stories(level,status);
CREATE INDEX IF NOT EXISTS ix_class_members_user ON class_members(user_id);
CREATE INDEX IF NOT EXISTS ix_parent_links_parent ON parent_links(parent_id);
CREATE INDEX IF NOT EXISTS ix_resources_story ON resources(story_id);
ALTER TABLE stories ENABLE ROW LEVEL SECURITY; ALTER TABLE classes ENABLE ROW LEVEL SECURITY; ALTER TABLE class_members ENABLE ROW LEVEL SECURITY; ALTER TABLE test_classes ENABLE ROW LEVEL SECURITY; ALTER TABLE question_bank ENABLE ROW LEVEL SECURITY; ALTER TABLE resources ENABLE ROW LEVEL SECURITY; ALTER TABLE import_jobs ENABLE ROW LEVEL SECURITY; ALTER TABLE parent_links ENABLE ROW LEVEL SECURITY; ALTER TABLE story_reads ENABLE ROW LEVEL SECURITY; ALTER TABLE rewards ENABLE ROW LEVEL SECURITY; ALTER TABLE announcements ENABLE ROW LEVEL SECURITY; ALTER TABLE settings ENABLE ROW LEVEL SECURITY; ALTER TABLE ai_usage ENABLE ROW LEVEL SECURITY;

INSERT INTO stories(title,level,story,summary,setting,time_period,characters,events,lesson,author,language,licence,source_name,status,created_at,updated_at) SELECT 'The Kind Farmer','P.1','A farmer named Kato had a small garden. One day, he saw a thirsty bird. He put water in a small dish. The bird drank and flew away. Kato smiled.','A farmer helps a thirsty bird.','A garden in a village','One sunny morning','["Kato: gave water to a thirsty bird"]','["Kato saw a thirsty bird","He put water in a dish","The bird drank and flew away"]','Kindness','Storybook School editorial team','English','Original school-created content','Storybook School','published',(EXTRACT(EPOCH FROM NOW())*1000)::BIGINT,(EXTRACT(EPOCH FROM NOW())*1000)::BIGINT WHERE NOT EXISTS (SELECT 1 FROM stories WHERE title='The Kind Farmer' AND level='P.1');
INSERT INTO stories(title,level,story,summary,setting,time_period,characters,events,lesson,author,language,licence,source_name,status,created_at,updated_at) SELECT 'Amina Shares Her Mangoes','P.1','Amina had two ripe mangoes. Her friend Musa had none. Amina cut one mango into two pieces. They sat under a tree and ate together.','Amina shares a mango with Musa.','Under a mango tree','One afternoon','["Amina: shared her mango","Musa: enjoyed the mango"]','["Amina had two mangoes","Musa had none","Amina shared one mango"]','Sharing','Storybook School editorial team','English','Original school-created content','Storybook School','published',(EXTRACT(EPOCH FROM NOW())*1000)::BIGINT,(EXTRACT(EPOCH FROM NOW())*1000)::BIGINT WHERE NOT EXISTS (SELECT 1 FROM stories WHERE title='Amina Shares Her Mangoes' AND level='P.1');
INSERT INTO stories(title,level,story,summary,setting,time_period,characters,events,lesson,author,language,licence,source_name,status,created_at,updated_at) SELECT 'The Missing School Bag','P.2','Peter could not find his school bag. He looked near the door and under his bed. His sister Sarah found it behind the chair. Peter thanked her and packed his books.','Peter finds his missing school bag with help from Sarah.','Peter’s home','In the morning','["Peter: looked for his bag","Sarah: found the bag"]','["Peter could not find his bag","He searched near the door","Sarah found it behind a chair","Peter thanked her"]','Being organised','Storybook School editorial team','English','Original school-created content','Storybook School','published',(EXTRACT(EPOCH FROM NOW())*1000)::BIGINT,(EXTRACT(EPOCH FROM NOW())*1000)::BIGINT WHERE NOT EXISTS (SELECT 1 FROM stories WHERE title='The Missing School Bag' AND level='P.2');
INSERT INTO stories(title,level,story,summary,setting,time_period,characters,events,lesson,author,language,licence,source_name,status,created_at,updated_at) SELECT 'The Helpful Neighbour','P.2','Nabirye was carrying a basket of sweet potatoes. The basket became too heavy. Her neighbour, Okello, offered to help. They carried it to her home. Nabirye thanked him.','A neighbour helps Nabirye carry a heavy basket.','A village path','One market day','["Nabirye: carried sweet potatoes","Okello: helped his neighbour"]','["Nabirye carried a basket","The basket became heavy","Okello helped her home"]','Cooperation','Storybook School editorial team','English','Original school-created content','Storybook School','published',(EXTRACT(EPOCH FROM NOW())*1000)::BIGINT,(EXTRACT(EPOCH FROM NOW())*1000)::BIGINT WHERE NOT EXISTS (SELECT 1 FROM stories WHERE title='The Helpful Neighbour' AND level='P.2');
INSERT INTO stories(title,level,story,summary,setting,time_period,characters,events,lesson,author,language,licence,source_name,status,created_at,updated_at) SELECT 'The Clean Water Project','P.3','Pupils at Bright Primary School noticed rubbish near their water source. Their teacher guided them to organise a clean-up. They collected litter, placed it in bins and made signs asking people to keep the area clean. Soon the water point looked better.','Pupils work together to protect their water source.','A school and nearby water point','During a school week','["The pupils: organised a clean-up","Their teacher: guided the activity"]','["Pupils saw rubbish near the water","The teacher guided a clean-up","They collected litter","They made reminder signs"]','Care for the environment','Storybook School editorial team','English','Original school-created content','Storybook School','published',(EXTRACT(EPOCH FROM NOW())*1000)::BIGINT,(EXTRACT(EPOCH FROM NOW())*1000)::BIGINT WHERE NOT EXISTS (SELECT 1 FROM stories WHERE title='The Clean Water Project' AND level='P.3');
INSERT INTO stories(title,level,story,summary,setting,time_period,characters,events,lesson,author,language,licence,source_name,status,created_at,updated_at) SELECT 'The Lost Calf','P.4','When a young calf failed to return to the kraal, Atim and her cousin Joel followed its hoofprints. They found it caught in a loose fence near the stream. Joel held the fence open while Atim guided the calf through. They informed their grandmother and repaired the fence together.','Atim and Joel find a calf and prevent it from getting lost again.','A family farm near a stream','Late afternoon','["Atim: followed hoofprints","Joel: helped free the calf","Grandmother: advised them"]','["The calf did not return","The children followed hoofprints","They found it by a fence","They freed it and told their grandmother","They repaired the fence"]','Responsibility and teamwork','Storybook School editorial team','English','Original school-created content','Storybook School','published',(EXTRACT(EPOCH FROM NOW())*1000)::BIGINT,(EXTRACT(EPOCH FROM NOW())*1000)::BIGINT WHERE NOT EXISTS (SELECT 1 FROM stories WHERE title='The Lost Calf' AND level='P.4');
INSERT INTO stories(title,level,story,summary,setting,time_period,characters,events,lesson,author,language,licence,source_name,status,created_at,updated_at) SELECT 'The Seedling That Survived','P.5','During a long dry spell, Sanyu noticed that the seedlings behind the classroom were wilting. She suggested using water left after washing vegetables. Her classmates agreed to collect it in a clean container. They watered the seedlings carefully and covered the soil with dry grass to reduce evaporation. After several days, new leaves appeared.','Learners save seedlings by reusing suitable water and protecting the soil.','A school garden','During a dry season','["Sanyu: suggested reusing suitable water","Classmates: cared for the seedlings"]','["The seedlings began to wilt","Sanyu suggested reusing water","Pupils collected the water","They watered and mulched the soil","New leaves appeared"]','Resourcefulness and conservation','Storybook School editorial team','English','Original school-created content','Storybook School','published',(EXTRACT(EPOCH FROM NOW())*1000)::BIGINT,(EXTRACT(EPOCH FROM NOW())*1000)::BIGINT WHERE NOT EXISTS (SELECT 1 FROM stories WHERE title='The Seedling That Survived' AND level='P.5');
INSERT INTO stories(title,level,story,summary,setting,time_period,characters,events,lesson,author,language,licence,source_name,status,created_at,updated_at) SELECT 'The Honest Market Seller','P.6','At the weekly market, Mugisha noticed that a customer had paid more than the price of the vegetables. The market was crowded, and nobody else had noticed the mistake. Mugisha called the customer back and returned the extra money. The customer thanked him, while another trader praised his honesty. Mugisha explained that trust was more valuable than a small extra payment.','Mugisha returns extra money and earns the trust of customers.','A busy village market','On market day','["Mugisha: returned extra money","Customer: thanked the seller","Another trader: praised his honesty"]','["A customer paid too much","Mugisha noticed the mistake","He called the customer back","He returned the extra money","The customer thanked him"]','Honesty builds trust','Storybook School editorial team','English','Original school-created content','Storybook School','published',(EXTRACT(EPOCH FROM NOW())*1000)::BIGINT,(EXTRACT(EPOCH FROM NOW())*1000)::BIGINT WHERE NOT EXISTS (SELECT 1 FROM stories WHERE title='The Honest Market Seller' AND level='P.6');

INSERT INTO schema_migrations(name,applied_at) VALUES('storybook-upgrade-001',(EXTRACT(EPOCH FROM NOW())*1000)::BIGINT) ON CONFLICT(name) DO NOTHING;
INSERT INTO classes(name,level,academic_year,created_at) SELECT 'P.'||n,'P.'||n,EXTRACT(YEAR FROM NOW())::TEXT,(EXTRACT(EPOCH FROM NOW())*1000)::BIGINT FROM generate_series(1,6) n ON CONFLICT(name,academic_year) DO NOTHING;
COMMIT;
